def answer_message(raw):
    """Delegasikan seluruh percakapan ke ChatbotEngine terpusat."""
    response = st.session_state.foodsy_engine.process_message(raw, st.session_state)
    # Sinkronkan data UI setelah chatbot melakukan perubahan di SQLite.
    st.session_state.inventory = get_inventory()
    st.session_state.shopping = get_shopping()
    return response


def pantry_icon(name):
    icons = {
        "stock": '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7.5 12 4l7 3.5v10L12 21l-7-3.5z" fill="none" stroke="#16866D" stroke-width="1.8" stroke-linejoin="round"/><path d="m5.5 7.7 6.5 3.4 6.5-3.4M12 11.1V21" fill="none" stroke="#16866D" stroke-width="1.8" stroke-linejoin="round"/></svg>',
        "expiry": '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5.5" width="16" height="15" rx="2.5" fill="none" stroke="#087F75" stroke-width="1.8"/><path d="M8 3.5v4M16 3.5v4M4 10h16" stroke="#087F75" stroke-width="1.8" stroke-linecap="round"/><circle cx="12" cy="15" r="2.5" fill="none" stroke="#087F75" stroke-width="1.6"/><path d="M12 13.5v1.7l1.1.7" stroke="#087F75" stroke-width="1.4" stroke-linecap="round"/></svg>',
        "shopping": '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9h16l-1.5 11h-13zM8 9l4-5 4 5" fill="none" stroke="#287B91" stroke-width="1.8" stroke-linejoin="round"/><path d="M9 13v3M15 13v3" stroke="#287B91" stroke-width="1.8" stroke-linecap="round"/></svg>',
    }
    return icons.get(name, "")

def bubble(message):
    safe = html.escape(message["content"])
    safe = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", safe)
    safe = re.sub(r"(?m)^-\s+", "• ", safe)
    safe = safe.replace("\n", "<br>")
    if message["role"] == "user":
        user_icon = '<svg viewBox="0 0 40 40" aria-hidden="true"><circle cx="20" cy="20" r="18" fill="#EEF4E9"/><circle cx="20" cy="14.5" r="5.8" fill="#6C9870"/><path d="M9.5 31.5c1.6-6.1 5.1-9.1 10.5-9.1s8.9 3 10.5 9.1" fill="#B7D4AC" stroke="#6C9870" stroke-width="1.5" stroke-linecap="round"/></svg>'
        return f'<div class="chat-row user"><div class="bubble">{safe}</div><div class="avatar">{user_icon}</div></div>'
    assistant_icon = f'<img src="{CHAT_AVATAR_URI}" alt="Foodsy Buddy avatar">'
    return f'<div class="chat-row bot"><div class="avatar">{assistant_icon}</div><div class="bubble">{safe}</div></div>'

